    storm: u => sky(u, '#5a6570', '#9aa4ad') + fx('drift', `<g fill="#46505a" opacity=".85"><ellipse cx="80" cy="18" rx="70" ry="20"/><ellipse cx="240" cy="14" rx="90" ry="20"/><ellipse cx="350" cy="22" rx="50" ry="16"/></g>`) + fx('bolt', `<path d="M262 30 L246 70 L260 70 L240 116 L282 58 L266 58 L280 30Z" fill="#f6e27a"/>`) + fx('bolt', `<rect width="${W}" height="${H}" fill="#fff" opacity=".25"/>`, 1.2) + tree(320, 146, 1.3, '#5f7a68') + `<rect y="146" width="${W}" height="24" fill="#5f6266"/>` + sceneRain('#c3cfd8', 1.4),
    shack: u => sky(u, '#9aa3a8', '#ccd0cf') + at(180, 92, '<path d="M0 56 V12 L40 -4 L80 12 V56Z" fill="#9b8a72"/><path d="M-6 14 L40 -8 L86 14" stroke="#6f6252" stroke-width="5" fill="none"/><rect x="30" y="26" width="18" height="30" fill="#6f6252"/><path d="M8 30 h14 M10 40 h12 M56 30 h14" stroke="#7d6f5c" stroke-width="2"/>') + at(300, 146, '<g fill="#8a7c6e"><ellipse cx="0" cy="-14" rx="22" ry="11"/><path d="M18 -20 Q28 -34 34 -30 Q36 -22 24 -14Z"/><path d="M28 -32 l2 -8 l3 7z M33 -31 l4 -7 l1 8z"/><path d="M-16 -6 v10 M-6 -6 v10 M6 -6 v10 M16 -6 v10" stroke="#6f6252" stroke-width="3"/><circle cx="30" cy="-25" r="1.2" fill="#2b2a28"/></g>' + fx('sway', '<path d="M-22 -16 q-8 6 -6 14" stroke="#6f6252" stroke-width="2" fill="none"/>')) + `<rect y="146" width="${W}" height="24" fill="#8d8173"/>` + fx('spin', at(340, 160, '<g stroke="#a69a76" stroke-width="1" fill="none"><circle r="8"/><path d="M-6 -4 Q0 6 6 -4 M-7 2 Q0 -6 7 3"/></g>')),
    bridge: u => sky(u, '#7f8a92', '#b7bec2') + `<rect x="150" y="30" width="${W - 150}" height="22" fill="#6f777d"/><path d="M180 52 V146 M300 52 V146" stroke="#5f666b" stroke-width="16"/><path d="M150 30 H${W}" stroke="#4f565b" stroke-width="4"/>` + T(240, 100, '', 10, '#fff') + `<path d="M196 90 q10 -6 20 0 q-10 6 -20 0" fill="#9aa3a8" opacity=".6"/><rect y="146" width="${W}" height="24" fill="#6a6f72"/>` + at(250, 146, '<path d="M-18 0 L-14 -20 L14 -20 L18 0Z" fill="#a98f6a"/><path d="M-14 -20 L-20 -28 M14 -20 L22 -28" stroke="#8c7452" stroke-width="2"/>') + sceneRain('#c3cfd8', .6),
    snow: u => sky(u, '#4f6378', '#9fb3c6') + `<path d="M0 120 Q100 104 200 118 T${W} 112 V${H} H0Z" fill="#e8f0f6"/><path d="M0 146 Q140 138 ${W} 146 V${H} H0Z" fill="#f6fafd"/>` + at(250, 100, '<rect width="60" height="40" fill="#8f9fae"/><path d="M-6 2 L30 -18 L66 2Z" fill="#f6fafd"/><rect x="24" y="16" width="12" height="24" fill="#5f6f7e"/><rect x="6" y="10" width="12" height="10" fill="#ffd98a"/>') + at(200, 132, '<path d="M0 0 V-40" stroke="#5f6f7e" stroke-width="3"/>' + fx('pulse', '<circle cy="-42" r="6" fill="#ffe7a0" opacity=".85"/>')) + tree(340, 132, 1.1, '#d9e6ef') + Array.from({ length: 24 }, (_, i) => at((i * 37) % W, 0, fx('snow', `<circle r="${1.6 + i % 3 * .6}" fill="#fff"/>`, (i * .37) % 2.6))).join(''),
